{
    for (volatile uint32_t i = 0; i < count; i++)
    {
        __asm("nop");
    }
}

int main(void)
{
    /* 1. Enable clock for the PORT and GPIO peripherals */
    CLOCK_EnableClock(kCLOCK_PortE);
    CLOCK_EnableClock(kCLOCK_GpioE);

    /* 2. Configure Pin Mux for PTE24 as GPIO */
    /* PORT_SetPinMux(portBase, pin, muxMode) */
    PORT_SetPinMux(PORT_E, LED_GPIO_PIN, 1);

    /* 3. Initialize GPIO pin as output */
    gpio_pin_config_t led_config = {
        .direction = kGPIO_DigitalOutput,
        .outValue = 0,
    };

    /* Use the SDK driver to init the pin */
    GPIO_PinInit(LED_GPIO_PORT, LED_GPIO_PIN, &led_config);

    while (1)
    {
        /* 4. Toggle the pin */
        GPIO_PortToggle(LED_GPIO_PORT, 1u << LED_GPIO_PIN);

        /* 5. Software delay */
        delay(100000);
    }

    return 0;
}

