#include <stdint.h>
#include <stdbool.h>
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_i2c.h"

/* Device Configuration */
#define SENSOR_I2C_BASE          I2C0
#define SENSOR_I2C_CLOCK        kCLOCK_I2c0Clk
#define SENSOR_I2C_BAUDRATE     100000
#define SENSOR_I2C_ADDR         0x68
#define REG_WHO_AM_I            0x75

/* Pin Configuration for MCXC144 */
#define SCL_PORT                PORTC
#define SCL_PIN                 8
#define SDA_PORT                PORTC
#define SDA_PIN                 9

int main(void)
{
    status_t status;
    uint8_t whoAmIValue = 0;
    uint8_t regAddr = REG_WHO_AM_I;

    /* 1. Enable Clock Gating */
    CLOCK_EnableClock(S_I2C0);

    /* 2. Configure Pin Muxing */
    /* SCL: PTC8 as I2C0_SCL */
    PORT_SetPinMux(SCL_PORT, SCL_PIN, PORT_MuxMode_Alt2);
    /* SDA: PTC9 as I2C0_SDA */
    PORT_SetPinMux(SDA_PORT, SDA_PIN, PORT_MuxMode_Alt2);

    /* 3. Initialize I2C Peripheral */
    i2c_master_config_t masterConfig;
    I2C_MasterGetDefaultConfig(&masterConfig);
    masterConfig.baudRate_Hz = SENSOR_I2C_BAUDRATE;

    status = I2C_MasterInit(S_I2C0, &masterConfig);
    if (status != kStatus_Success)
    {
        while (1); // Handle Init Error
    }

    /* 4. Read WHO_AM_I Register */
    /* Step A: Write the register address we want to read from */
    status = I2C_MasterTransferBlocking(S_I2C0, SENSOR_I2C_ADDR, &regAddr, 1, NULL, 0, 100);
    if (status != kStatus_Success)
    {
        while (1); // Handle Write Error
    }

    /* Step B: Read the value from the sensor */
    status = I2C_MasterTransferBlocking(S_I2C0, SENSOR_I2C_ADDR, NULL, 0, &whoAmIValue, 1, 100);
    if (status != kStatus_Success)
    {
        while (1); // Handle Read Error
    }

    /* Result is now stored in whoAmIValue */
    while (1)
    {
        __asm("nop");
    }
}

