#include <stdbool.h>
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_pit.h"

/* Hardware Definitions */
#define INPUT_PIN       3    // PTC3
#define INPUT_PORT      PORTC
#define INPUT_GPIO      GPIOC

#define LED_PIN         24   // PTE24
#define LED_PORT        PORTE
#define LED_GPIO        GPIOE

#define PIT_BASE_CLOCK  48000000UL 
#define SAMPLE_PERIOD_MS 10
#define PIT_LOAD_VALUE  ((PIT_BASE_CLOCK / 1000) * SAMPLE_PERIOD_MS)

/* Shared Variables */
volatile bool g_sampleReady = false;
volatile uint8_t g_sampleValue = 0;

void PIT0_IRQHandler(void)
{
    /* Clear interrupt flag */
    PIT_ClearInterruptFlags(PIT, kPIT_Timer0);

    /* Sample digital input PTC3 */
    g_sampleValue = GPIO_PinRead(INPUT_GPIO, INPUT_PIN);

    /* Signal main loop */
    g_sampleReady = true;
}

int main(void)
{
    /* 1. Initialize Clocks */
    /* fsl_clock.h provides the clock gating for peripherals */
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_PortE);
    CLOCK_EnableClock(kCLOCK_GpioC);
    CLOCK_EnableClock(kCLOCK_GpioE);
    CLOCK_EnableClock(kCLOCK_Pit);

    /* 2. Configure Pin Muxing */
    /* Configure PTC3 as GPIO */
    PORT_SetPinMux(INPUT_PORT, INPUT_PIN, kPORT_MuxAsGpio);
    /* Configure PTE24 as GPIO */
    PORT_SetPinMux(LED_PORT, LED_PIN, kPORT_MuxAsGpio);

    /* 3. Configure GPIO */
    /* Set PTC3 as input */
    GPIO_PinInit(INPUT_GPIO, INPUT_PIN, 0); 
    /* Set PTE24 as output */
    GPIO_PinInit(LED_GPIO, LED_PIN, 1);

    /* 4. Configure PIT (Periodic Interrupt Timer) */
    pit_config_t pitConfig;
    PIT_GetDefaultConfig(&pitConfig);

    /* Initialize PIT and set period for Channel 0 */
    PIT_Init(PIT, &pitConfig);
    PIT_SetTimerPeriod(PIT, 0, PIT_LOAD_VALUE);

    /* Enable interrupt for Channel 0 */
    PIT_EnableInterrupts(PIT, kPIT_Timer0);

    /* Enable PIT interrupt in NVIC */
    EnableIRQ(PIT_IRQn);

    /* Start the timer */
    PIT_StartTimer(PIT, 0);

    while (1)
    {
        if (g_sampleReady)
        {
            /* Atomic read of shared variables */
            uint8_t currentSample;

            /* Disable interrupts briefly to prevent race condition during read */
            __disable_irq();
            currentSample = g_sampleValue;
            g_sampleReady = false;
            __enable_irq();

            /* Logic: If input pin is high, toggle LED */
            if (currentSample != 0)
            {
                GPIO_PortToggle(LED_GPIO, 1u << LED_PIN);
            }
        }
    }
}

