#include <stdint.h>
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_spi.h"

/* SPI0 Pin Configuration (MCXC144) */
#define SPI0_SCK_PORT  PORTC
#define SPI0_SCK_PIN   6u
#define SPI0_MOSI_PORT PORTC
#define SPI0_MOSI_PIN  7u
#define SPI0_MISO_PORT PORTC
#define SPI0_MISO_PIN  4u
#define SPI0_CS_PORT   PORTC
#define SPI0_CS_PIN    5u

int main(void)
{
    /* Initialize system clocks */
    CLOCK_InitBoard();

    /* 1. Enable Clock Gating for Peripherals */
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_Spi0);

    /* 2. Configure Pin Muxing */
    /* SCK: PTC6 */
    PORT_SetPinMux(SPI0_SCK_PORT, SPI0_SCK_PIN, kPORT_MuxAlt2); 
    /* MOSI: PTC7 */
    PORT_SetPinMux(SPI0_MOSI_PORT, SPI0_MOSI_PIN, kPORT_MuxAlt2);
    /* MISO: PTC4 */
    PORT_SetPinMux(SPI0_MISO_PORT, SPI0_MISO_PIN, kPORT_MuxAlt2);

    /* 3. Configure Manual CS Pin (GPIO) */
    GPIO_PinInit(SPI0_CS_PORT, SPI0_CS_PIN, &GPIO_Pin_Init_ConfigStruct);
    GPIO_PinWrite(SPI0_CS_PORT, SPI0_CS_PIN, 1u); // Deassert High

    /* 4. SPI Configuration */
    spi_master_config_t masterConfig;
    SPI_MasterGetDefaultConfig(&masterConfig);

    masterConfig.baudRate = 1000000u;      // 1 MHz
    masterConfig.cpol = kSPI_CpolLow;     // CPOL = 0
    masterConfig.cpha = kSPI_CphaLow;     // CPHA = 0
    masterConfig.pcsSelect = kSPI_Pcs0;   // Using manual CS, but driver needs a PCS selection
    masterConfig.sckDelay = kSPI_SckDelay_Disabled;

    status_t status = SPI_MasterInit(SPI0, &masterConfig);
    if (status != kStatus_Success) {
        while (1); // Error handling
    }

    /* Data buffers */
    uint8_t txData[2] = {0x9F, 0x00};
    uint8_t rxData[2] = {0, 0};

    while (1) {
        /* Assert CS Low */
        GPIO_PinWrite(SPI0_CS_PORT, SPI0_CS_PIN, 0u);

        /* Synchronous Transfer: Send 2 bytes, receive 2 bytes */
        status = SPI_MasterTransferBlocking(SPI0, &masterConfig, txData, rxData, 2);

        /* Deassert CS High */
        GPIO_PinWrite(SPI0_CS_PORT, SPI0_CS_PIN, 1u);

        if (status == kStatus_Success) {
            /* rxData now contains the 2 received bytes */
        }

        /* Simple delay before next poll */
        for (volatile int i = 0; i < 100000; i++);
    }
}

