#define SPI0_CS_GPIO   GPIOC
#define SPI0_CS_PORT   PORTC
#define SPI0_CS_PIN    5u

int main(void)
{
    /* 1. Enable Clock Gating for Peripherals */
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_GpioC);
    CLOCK_EnableClock(kCLOCK_Spi0);

    /* 2. Configure Pin Muxing */
    /* SCK: PTC6, MOSI: PTC7, MISO: PTC4 */
    PORT_SetPinMux(SPI0_SCK_PORT, SPI0_SCK_PIN, kPORT_MuxAlt2); 
    PORT_SetPinMux(SPI0_MOSI_PORT, SPI0_MOSI_PIN, kPORT_MuxAlt2);
    PORT_SetPinMux(SPI0_MISO_PORT, SPI0_MISO_PIN, kPORT_MuxAlt2);

    /* CS: PTC5 as GPIO */
    PORT_SetPinMux(SPI0_CS_PORT, SPI0_CS_PIN, kPORT_MuxGpio);

    /* 3. Configure Manual CS Pin (GPIO) */
    gpio_pin_config_t csConfig = {
        .pinDirection = kGPIO_PinOutput,
        .pinOutputType = kGPIO_DigitalOutput,
        .pinWriteBehavior = kGPIO_WriteClear,
    };
    GPIO_PinInit(SPI0_CS_GPIO, SPI0_CS_PIN, &csConfig);
    GPIO_PinWrite(SPI0_CS_GPIO, SPI0_CS_PIN, 1u); // Deassert High

    /* 4. SPI Configuration */
    spi_master_config_t masterConfig;
    SPI_MasterGetDefaultConfig(&masterConfig);

    /* Use correct SDK field names for MCX/Kinetis family */
    masterConfig.baudRate_Bps = 1000000u;      // 1 MHz
    masterConfig.clockPhase = kSPI_ClockPhaseLow; // CPHA = 0
    masterConfig.clockPolarity = kSPI_ClockPolarityLow; // CPOL = 0

    /* Get the clock frequency for the SPI peripheral to calculate prescalers */
    uint32_t spiClock = CLOCK_GetSpiClkFreq(0);

    status_t status = SPI_MasterInit(SPI0, &masterConfig, spiClock);
    if (status != kStatus_Success) {
        while (1);
    }

    /* Data buffers */
    uint8_t txData[2] = {0x9F, 0x00};
    uint8_t rxData[2] = {0, 0};

    /* Use spi_transfer_t for the SDK Blocking API */
    spi_transfer_t xfer;
    xfer.txData = txData;
    xfer.rxData = rxData;
    xfer.dataSize = 2;

    while (1) {
        /* Assert CS Low */
        GPIO_PinWrite(SPI0_CS_GPIO, SPI0_CS_PIN, 0u);

        /* Synchronous Transfer */
        status = SPI_MasterTransferBlocking(SPI0, &xfer);

        /* Deassert CS High */
        GPIO_PinWrite(SPI0_CS_GPIO, SPI0_CS_PIN, 1u);

        if (status == kStatus_Success) {
            /* rxData contains the received bytes */
        }

        /* Delay */
        for (volatile int i = 0; i < 100000; i++);
    }
}

