#include <stdint.h>
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_uart.h"

/* UART Configuration */
#define UART_BASE_ADDR    UART0
#define UART_BAUD_RATE    115200
#define UART_TX_PIN       kPORT_A_2
#define UART_RX_PIN       kPORT_A_1
#define UART_PORT         PORTA

/* Simple software delay function */
void delay_ms(uint32_t ms) {
    /* Rough approximation for Cortex-M0+ @ default clock */
    for (volatile uint32_t i = 0; i < ms * 2000; i++) {
        __NOP();
    }
}

int main(void) {
    status_t status;

    /* 1. Enable Clock for PORTA and UART0 */
    CLOCK_EnableClock(kCLOCK_PortA);
    CLOCK_EnableClock(kCLOCK_Uart0);

    /* 2. Configure Pin Mux for UART0 */
    /* TX Pin: PTA2 */
    PORT_SetPinMux(UART_PORT, UART_TX_PIN, kPORT_MuxAlt2); 
    /* RX Pin: PTA1 */
    PORT_SetPinMux(UART_PORT, UART_RX_PIN, kPORT_MuxAlt2);

    /* 3. Initialize UART0 */
    uart_config_t config;
    UART_GetDefaultConfig(&config);
    config.baudRate_Bps = UART_BAUD_RATE;
    config.enableTx = true;
    config.enableRx = true;

    status = UART_Init(UART_BASE_ADDR, &config, CLOCK_GetFreq(kCLOCK_Uart0));
    if (status != kStatus_Success) {
        while (1); // Hardware init failure
    }

    const char *msg = "Hello\r\n";
    uint8_t msg_len = 7;

    while (1) {
        /* 4. Transmit string blocking */
        /* UART_WriteBlocking is the SDK idiomatic way to send a buffer */
        status = UART_WriteBlocking(UART_BASE_ADDR, (uint8_t *)msg, msg_len);

        if (status == kStatus_Success) {
            /* 5. 1-second software delay */
            delay_ms(1000);
        }
    }

    return 0;
}

