#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_edma.h"

/* Constants */
#define BUFFER_SIZE 512
#define DMA_CHANNEL 0

/* Memory buffers must be aligned for DMA efficiency */
static uint8_t src_buffer[BUFFER_SIZE] __attribute__((aligned(32)));
static uint8_t dst_buffer[BUFFER_SIZE] __attribute__((aligned(32)));

int main(void)
{
    /* 1. Enable Clock for DMA0 */
    CLOCK_EnableClock(kCLOCK_Dma0);

    /* 2. Initialize eDMA */
    /* DMA_Init initializes the eDMA controller and sets up the internal state */
    DMA_Init(DMA0);

    /* 3. Prepare Source Buffer */
    for (int i = 0; i < BUFFER_SIZE; i++)
    {
        src_buffer[i] = (uint8_t)(i & 0xFF);
    }

    /* 4. Configure TCD (Transfer Control Descriptor) for Channel 0 */
    /* We use the SDK driver to configure the TCD for a memory-to-memory transfer */
    edma_tcd_t tcd;

    /* Initialize TCD with default values */
    memset(&tcd, 0, sizeof(edma_tcd_t));

    /* Source address */
    tcd.sourceAddress = (uint32_t)src_buffer;
    /* Destination address */
    tcd.destAddress = (uint32_t)dst_buffer;
    /* Transfer size in bytes */
    tcd.majorRequest = BUFFER_SIZE;
    /* Minor loop is not used for simple mem-to-mem, so major = total bytes */
    tcd.minorRequest = 1;
    /* Size of single transfer: 1 byte */
    tcd.nBytesCsg = 1;

    /* Source/Destination increment: 1 byte */
    tcd.sourceOffset = 1;
    tcd.destOffset = 1;

    /* Configure TCD for the specific channel */
    DMA_InstallTCD(DMA0, DMA_CHANNEL, &tcd);

    /* 5. Trigger Transfer */
    /* For memory-to-memory transfers on i.MX RT, we manually trigger the channel */
    DMA_EnableChannel(DMA0, DMA_CHANNEL);

    /* Wait for the transfer to complete by polling the channel status */
    /* In a production environment, an interrupt would be used */
    while (DMA_GetChannelStatusFlags(DMA0, DMA_CHANNEL) & kDMA_ChannelSB_Flag)
    {
        /* Wait for the channel to be disabled (transfer complete) */
        /* Note: The SDK behavior for simple mem-to-mem usually clears the enable bit upon completion */
    }

    /* Ensure all memory operations are complete (Data Synchronization Barrier) */
    __DSB();

    /* 6. Verification */
    for (int i = 0; i < BUFFER_SIZE; i++)
    {
        if (src_buffer[i] != dst_buffer[i])
        {
            /* Halt on mismatch */
            while (1);
        }
    }

    /* Success - Loop forever */
    while (1)
    {
        __WFI();
    }
}

