    transfer_config.destOffset = 1;
    transfer_config.majorRequestCount = 1;
    transfer_config.minorTransferCount = BUFFER_SIZE;
    transfer_config.sourceSizing = kEDMA_SizingByte;
    transfer_config.destSizing = kEDMA_SizingByte;

    /* Prepare the TCD for the transfer */
    EDMA_PrepareTransfer(&dma_handle, &transfer_config);

    /* 5. Trigger Transfer */
    /* Memory-to-memory transfers are triggered by software (setting the DER bit) */
    EDMA_StartTransfer(&dma_handle);

    /* 6. Wait for transfer to complete */
    /* Poll the TCD status until the Major Loop is complete (TCD is disabled) */
    /* We check the TCD control register's enable bit for the specific channel */
    while (DMA0->ER[DMA_CHANNEL] & DMA_ER_TCDDIS_MASK)
    {
        /* The SDK's EDMA_StartTransfer sets the DER bit. 
           The transfer is finished when the TCD is disabled (TCDDIS set).
           Note: In some SDK versions, you might poll the CSR or TCD register.
           We loop until the hardware clears the active status. */
    }

    /* Fallback: Since the RT series may handle TCDDIS differently in software trigger,
       we can also verify the completion by checking the TCD status. */
    while (!(DMA0->TCD[DMA_CHANNEL].CPSR & DMA_TCD_CPSR_S_MASK))
    {
        /* Wait for the TCD to be disabled/complete */
    }

    /* Ensure all memory operations are complete (Data Synchronization Barrier) */
    __DSB();

    /* 7. Verification */
    for (int i = 0; i < BUFFER_SIZE; i++)
    {
        if (src_buffer[i] != dst_buffer[i])
        {
            /* Halt on mismatch */
            while (1);
        }
    }

    /* Success - Loop forever */
    while (1)
    {
        __WFI();
    }
}

