    edma_config_t dma_config;
    EDMA_GetDefaultConfig(&dma_config);
    EDMA_Init(DMA0, &dma_config);

    /* 3. Prepare Source Buffer */
    for (int i = 0; i < BUFFER_SIZE; i++)
    {
        src_buffer[i] = (uint8_t)(i & 0xFF);
    }

    /* 4. Configure DMA Transfer 
       In the RT SDK, EDMA_PrepareTransfer takes a config struct that 
       contains the TCD details. */
    edma_transfer_config_t transfer_config;
    memset(&transfer_config, 0, sizeof(edma_transfer_config_t));

    transfer_config.srcAddr = (uint32_t)src_buffer;
    transfer_config.destAddr = (uint32_t)dst_buffer;
    transfer_config.srcOffset = 1;
    transfer_config.destOffset = 1;
    transfer_config.majorRequestCount = 1;
    transfer_config.minorTransferCount = BUFFER_SIZE;
    /* Sizing: 1 = byte, 2 = half-word, 4 = word */
    transfer_config.srcSizing = 1; 
    transfer_config.destSizing = 1;

