           use an interrupt or check the Specific TCD status. 
           We check the CSR for the 'Done' event or the TCD's status. */
        if (!(DMA0->CSR[DMA_CHANNEL] & DMA_CSR_ESG_MASK)) break;
    }

    /* Ensure memory consistency (Data Synchronization Barrier) */
    __DSB();

    /* 7. Verification */
    for (int i = 0; i < BUFFER_SIZE; i++)
    {
        if (src_buffer[i] != dst_buffer[i])
        {
            /* Halt on mismatch */
            while (1);
        }
    }

    /* Success - Loop forever */
    while (1)
