#include <fsl_gpio.h>

/* Hardware Definitions */
#define LED_GPIO_PORT  GPIO1
#define LED_GPIO_PIN   3U
#define LED_PAD_MUX    IOMUXC_GPIO_AD_04

/* Simple software delay loop */
void delay_ms(uint32_t ms) {
    /* Rough approximation for Cortex-M7 at typical clock speeds */
    volatile uint32_t count = ms * 10000; 
    while (count--) {
        __NOP();
    }
}

int main(void) {
    /* 1. Initialize Clock */
    /* Enabling the clock for the GPIO peripheral */
    CLOCK_EnableClock(kCLOCK_Gpio1);

    /* 2. Configure Pin Mux */
    /* Set GPIO_AD_04 to GPIO mode */
    iomuxc_gpio_ad_04_config_t led_mux_config = {
        .mux_mode = 0, // GPIO mode
        .pad_ctrl = 0x100, // Default pull-up/drive strength
    };
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_04, 0);

    /* 3. Configure GPIO */
    /* Initialize GPIO1 pin 3 as output */
    gpio_pd_config_t led_config = {
        .targetPin = LED_GPIO_PIN,
        .direction = kGPIO_DigitalOutput,
        .internalPullEnable = kGPIO_PullDisable,
        .passiveFilterEnable = kGPIO_PassiveFilterDisable,
        .driveStrength = kGPIO_DriveStrengthLow,
    };

    GPIO_PinInit(LED_GPIO_PORT, LED_GPIO_PIN, &led_config);

    /* 4. Requirement: LED off at startup */
    GPIO_PinWrite(LED_GPIO_PORT, LED_GPIO_PIN, 0U);

    while (1) {
        /* Toggle the LED */
        GPIO_PortToggle(LED_GPIO_PORT, 1U << LED_GPIO_PIN);

        /* Delay roughly 500ms */
        delay_ms(500);
    }

    return 0;
}

