/* Configuration Constants */
#define SENSOR_I2C_ADDR    0x68
#define REG_WHO_AM_I        0x75
#define I2C_BAUDRATE       400000

int main(void)
{
    /* 1. Clock Configuration */
    /* Enable clock to LPI2C1 peripheral */
    CLOCK_EnableClock(kCLOCK_Lpi2c1);

    /* 2. Pin Muxing */
    /* GPIO_AD_08 -> LPI2C1_SCL */
    IOMUXC_SetPinMuxConfig(IOMUXC_GPIO_AD_08_LPI2C1_SCL, 0);
    /* GPIO_AD_09 -> LPI2C1_SDA */
    IOMUXC_SetPinMuxConfig(IOMUXC_GPIO_AD_09_LPI2C1_SDA, 0);

    /* 3. Peripheral Initialization */
    lpi2c_master_config_t masterConfig;
    LPI2C_GetDefaultMasterConfig(&masterConfig);

    /* Calculate baud rate based on the LPI2C clock source */
    /* Note: LPI2C clock is typically derived from the system clock or a specific bus clock */
    uint32_t lpi2cClock = clock_get_root(kCLOCK_Lpi2c);
    masterConfig.baudRate = I2C_BAUDRATE;

    LPI2C_InitIsDoneCmd(LPI2C1, &masterConfig);

    /* 4. I2C Transaction */
    uint8_t regAddr = REG_WHO_AM_I;
    uint8_t whoAmIValue = 0;
    status_t status;

    /* Master Write: Send the register address we want to read */
    status = LPI2C_MasterTransferBlocking(LPI2C1, SENSOR_I2C_ADDR, &regAddr, 1, kLPI2C_Write);
    if (status != kStatus_Success) {
        while (1); // Error handling
    }

    /* Master Read: Read 1 byte from the sensor */
    status = LPI2C_MasterTransferBlocking(LPI2C1, SENSOR_I2C_ADDR, &whoAmIValue, 1, kLPI2C_Read);
    if (status != kStatus_Success) {
        while (1); // Error handling
    }

    /* The result is now stored in whoAmIValue */
    while (1) 
    {
        __ asm("nop");
    }
}

