    IOMUXC_SetPinMuxConfig(IOMUXC_GPIO_AD_09_LPI2C1_SDA, 0);

    /* 3. Peripheral Initialization */
    lpi2c_master_config_t masterConfig;
    LPI2C_MasterGetDefaultConfig(&masterConfig);

    masterConfig.baudRate_Hz = I2C_BAUDRATE;

    /* Get source clock frequency for LPI2C1 */
    uint32_t lpi2c_clock_hz = CLOCK_GetLpi2cClkFreq(1); 
    LPI2C_MasterInit(LPI2C1, &masterConfig, lpi2c_clock_hz);

    /* 4. I2C Transaction */
    uint8_t regAddr = REG_WHO_AM_I;
    uint8_t whoAmIValue = 0;
    status_t status;

    /* LPI2C_MasterTransferBlocking uses lpi2c_master_transfer_t */
    lpi2c_master_transfer_t transfer;

    /* Step A: Write the register address to the sensor */
    transfer.slaveAddress = SENSOR_I2C_ADDR;
    transfer.flags = kLPI2C_TransferDefaultFlag;
    transfer.data = &regAddr;
    transfer.dataSize = 1;
    transfer.direction = kLPI2C_Write;

    status = LPI2C_MasterTransferBlocking(LPI2C1, &transfer);
    if (status != kStatus_Success) {
        while (1); // Error handling
    }

    /* Step B: Read the register value from the sensor */
    transfer.slaveAddress = SENSOR_I2C_ADDR;
    transfer.flags = kLPI2C_TransferDefaultFlag;
    transfer.data = &whoAmIValue;
    transfer.dataSize = 1;
    transfer.direction = kLPI2C_Read;

    status = LPI2C_MasterTransferBlocking(LPI2C1, &transfer);
    if (status != kStatus_Success) {
        while (1); // Error handling
    }

    /* The result is now stored in whoAmIValue */
    while (1) 
    {
        __asm("nop");
    }
}

