#include <fsl_common.h>
#include <fsl_clock.h>
#include <fsl_iomuxc.h>
#include <fsl_lpuart.h>

/* Peripheral Configuration */
#define UART_BASE LPUART1
#define UART_BAUD_RATE 115200u

int main(void)
{
    /* 1. Clock Configuration 
     * In a full system, the system clock would be configured here. 
     * We enable the clock for LPUART1. */
    CLOCK_EnableClock(kCLOCK_Lpuart1, 0);

    /* 2. Pin Mux Configuration
     * GPIO_AD_24 -> LPUART1 TX
     * GPIO_AD_25 -> LPUART1 RX */
    iomuxc_gpio_alt_set(MIMO_MXRT1176_GPIO_AD_24, 2); // LPUART1 TX
    iomuxc_gpio_alt_set(MIMO_MXRT1176_GPIO_AD_25, 2); // LPUART1 RX

    /* 3. LPUART Configuration */
    lpuart_config_t uartConfig;

    /* Get default configuration (8N1) */
    LPUART_GetDefaultConfig(&uartConfig);
    uartConfig.baudRate = UART_BAUD_RATE;
    uartConfig.txSlewRate = kLpuartSlewRateFast;
    uartConfig.rxSlewRate = kLpuartSlewRateFast;

    /* Initialize LPUART1 */
    LPUART_Init(UART_BASE, &uartConfig, CLOCK_GetSrcClock(kCLOCK_Lpuart1));

    while (1)
    {
        /* 4. Echo Logic: Read one byte and write it back */

        /* Wait for character to be received (Blocking) */
        if (LPUART_GetTxHwMFlag(UART_BASE) == 0) 
        {
            /* We check if there is data available in the RX buffer */
            if (LPUART_GetRxHwMFlag(UART_BASE) != 0)
            {
                uint8_t data = LPUART_ReadByte(UART_BASE);

                /* Write the byte back immediately */
                LPUART_WriteByte(UART_BASE, data);
            }
        }
        else
        {
            /* Wait for RX data */
            uint8_t data = LPUART_ReadByte(UART_BASE);
            LPUART_WriteByte(UART_BASE, data);
        }
    }

    return 0;
}

/* Note: The actual implementation of LPUART_ReadByte/WriteByte 
   and the specific IOMUXC macros vary slightly by SDK version, 
   but follow the fsl_lpuart.h and fsl_iomuxc.h driver patterns. */

#include <fsl_common.h>
#include <fsl_clock.h>
#include <fsl_iomuxc.h>
#include <fsl_lpuart.h>

/* Peripheral Configuration */
#define UART_BASE LPUART1
#define UART_BAUD_RATE 115200u

int main(void)
{
    /* 1. Clock Configuration 
     * Enable the clock for LPUART1. 
     * On RT1170, CLOCK_EnableClock takes only the clock name. */
    CLOCK_EnableClock(kCLOCK_Lpuart1);

    /* 2. Pin Mux Configuration
     * GPIO_AD_24 -> LPUART1 TX
     * GPIO_AD_25 -> LPUART1 RX 
     * Using IOMUXC_SetPinMux for the RT series. */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_24_ALT0, 0); // Alt 0 is LPUART1 TX
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_25_ALT0, 0); // Alt 0 is LPUART1 RX

    /* 3. LPUART Configuration */
    lpuart_config_t uartConfig;

    /* Get default configuration (8N1) */
    LPUART_GetDefaultConfig(&uartConfig);

    /* Correct member name for baud rate in SDK is baudRate_Bps */
    uartConfig.baudRate_Bps = UART_BAUD_RATE;

    /* Initialize LPUART1. 
       LPUART_Init requires the base, config, and the clock frequency.
       The clock frequency is retrieved via clock_get_root_clock or similar,
       but for bare-metal SDKs, the clock source is often derived from 
       the root clock of the peripheral. */
    LPUART_Init(UART_BASE, &uartConfig, CLOCK_GetSrcClock(kCLOCK_Lpuart1));

    while (1)
    {
        /* 4. Echo Logic: Read one byte and write it back */

        /* Check if data is available in the receive buffer */
        if (LPUART_GetStatusFlags(UART_BASE) & kLPUART_RxSflg)
        {
            /* Read one byte */
            uint8_t data = LPUART_ReadByte(UART_BASE);

            /* Wait for Transmit buffer to be empty then write it back */
            while (!(LPUART_GetStatusFlags(UART_BASE) & kLPUART_TdBeflg));
            LPUART_WriteByte(UART_BASE, data);
        }
    }

    return 0;
}

#include <fsl_common.h>
