#include <fsl_lpuart.h>

/* Peripheral Configuration */
#define UART_BASE LPUART1
#define UART_BAUD_RATE 115200u

int main(void)
{
    /* 1. Clock Configuration 
     * Enable the clock for LPUART1. */
    CLOCK_EnableClock(kCLOCK_Lpuart1);

    /* 2. Pin Mux Configuration
     * GPIO_AD_24 -> LPUART1 TX (ALT 2)
     * GPIO_AD_25 -> LPUART1 RX (ALT 2)
     * IOMUXC_SetPinMux(muxRegister, muxMode)
     */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_24_MUX, 2); 
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_25_MUX, 2);

    /* 3. LPUART Configuration */
    lpuart_config_t uartConfig;

    /* Get default configuration (8N1) */
    LPUART_GetDefaultConfig(&uartConfig);

    /* Set baud rate */
    uartConfig.baudRate_Bps = UART_BAUD_RATE;

    /* Initialize LPUART1.
       LPUART_Init requires the base, config, and the source clock frequency.
       On RT1170, the LPUART clock is typically derived from a root clock. 
       We use the SDK's clocking API to retrieve the frequency. */
    LPUART_Init(UART_BASE, &uartConfig, clock_get_root(kCLOCK_Lpuart1));

    while (1)
    {
        /* 4. Echo Logic: Read one byte and write it back */

        /* Check if data is available in the receive buffer (IFS register)
         * kLPUART_RxSflg is the flag for "Receiver buffer contains data" */
        if (LPUART_GetStatusFlags(UART_BASE) & kLPUART_RxSflg)
        {
            /* Read one byte */
            uint8_t data = LPUART_ReadByte(UART_BASE);

            /* Wait for Transmit buffer to be empty (TDF flag)
             * kLPUART_TdBeflg is the flag for "Transmit data buffer empty" */
            while (!(LPUART_GetStatusFlags(UART_BASE) & kLPUART_TdBeflg));

            /* Write it back */
            LPUART_WriteByte(UART_BASE, data);
        }
    }

    return 0;
}

