/* Peripheral Configuration */
#define UART_BASE LPUART1
#define UART_BAUD_RATE 115200u

int main(void)
{
    /* 1. Clock Configuration 
     * Enable the clock for LPUART1. */
    CLOCK_EnableClock(kCLOCK_Lpuart1);

    /* 2. Pin Mux Configuration
     * GPIO_AD_24 -> LPUART1 TX (ALT 2)
     * GPIO_AD_25 -> LPUART1 RX (ALT 2)
     * IOMUXC_SetPinMux requires (muxRegister, muxMode)
     * On RT1170, the registers are defined as IOMUXC_GPIO_AD_24_MUX and IOMUXC_GPIO_AD_25_MUX
     */
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_24_MUX, 2); 
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_25_MUX, 2);

    /* 3. LPUART Configuration */
    lpuart_config_t uartConfig;

    /* Get default configuration (8N1) */
    LPUART_GetDefaultConfig(&uartConfig);

    /* Set baud rate */
    uartConfig.baudRate_Bps = UART_BAUD_RATE;

    /* Initialize LPUART1.
       For RT1170, we use the clock frequency of the peripheral. 
       Since we are bare-metal without a board file, we use the SDK's 
       clock_get_root_frequency or the internal clocking system. 
       Note: LPUART_Init expects the source clock frequency in Hz. */
    LPUART_Init(UART_BASE, &uartConfig, 24000000U); // Assuming 24MHz default root clock for LPUART

    while (1)
    {
        /* 4. Echo Logic: Read one byte and write it back */

        /* Check if data is available in the receive buffer.
           kLPUART_RDRF = Receive Data Register Full */
        if (LPUART_GetStatusFlags(UART_BASE) & kLPUART_RDRF)
        {
            /* Read one byte */
            uint8_t data = LPUART_ReadByte(UART_BASE);

            /* Wait for Transmit data buffer to be empty (TDRE)
               kLPUART_TDRE = Transmit Data Register Empty */
            while (!(LPUART_GetStatusFlags(UART_BASE) & kLPUART_TDRE));

            /* Write it back */
            LPUART_WriteByte(UART_BASE, data);
        }
    }

    return 0;
}

#include <fsl_common.h>
#include <fsl_clock.h>
#include <fsl_iomuxc.h>
#include <fsl_lpuart.h>

/* Peripheral Configuration */
#define UART_BASE LPUART1
#define UART_BAUD_RATE 115200u

/* 
 * For RT1170, IOMUXC_SetPinMux requires the specific register address 
 * and the mux mode. We use the register offsets found in fsl_iomuxc.h.
 * LPUART1 TX: GPIO_AD_24 (ALT 2)
 * LPUART1 RX: GPIO_AD_25 (ALT 2)
 */
#define UART_TX_MUX_REG IOMUXC_GPIO_AD_24_MUX
#define UART_RX_MUX_REG IOMUXC_GPIO_AD_25_MUX

int main(void)
{
    /* 1. Clock Configuration 
     * Enable the clock for LPUART1. */
    CLOCK_EnableClock(kCLOCK_Lpuart1);

    /* 2. Pin Mux Configuration
     * Set the pins to the LPUART1 function (Alt 2)
     * IOMUXC_SetPinMux(uint32_t muxRegister, uint32_t muxMode)
     */
    IOMUXC_SetPinMux(UART_TX_MUX_REG, 2); 
    IOMUXC_SetPinMux(UART_RX_MUX_REG, 2);

    /* 3. LPUART Configuration */
    lpuart_config_t uartConfig;

    /* Get default configuration (8N1) */
    LPUART_GetDefaultConfig(&uartConfig);

    /* Set baud rate */
    uartConfig.baudRate_Bps = UART_BAUD_RATE;

    /* Initialize LPUART1.
       LPUART_Init expects the source clock frequency in Hz.
       On RT1170, the LPUARTs often default to a 24MHz source clock. */
    LPUART_Init(UART_BASE, &uartConfig, 24000000U);

    while (1)
    {
        /* 4. Echo Logic: Read one byte and write it back */

        /* Check if data is available in the receive buffer.
           LPUART_GetStatusFlags returns the status register.
           We check the RDRF (Receive Data Register Full) bit.
           In the SDK, this is typically defined as kLPUART_SPSR_RDRF or similar,
           but we can use the bit mask 0x1U which corresponds to RDRF in the SPSR. */
        if (LPUART_GetStatusFlags(UART_BASE) & 0x1U) 
        {
            /* Read one byte */
            uint8_t data = LPUART_ReadByte(UART_BASE);

            /* Wait for Transmit data buffer to be empty (TDRE)
               TDRE is the 2nd bit (0x2U) in the SPSR. */
            while (!(LPUART_GetStatusFlags(UART_BASE) & 0x2U));

            /* Write it back */
            LPUART_WriteByte(UART_BASE, data);
        }
    }

    return 0;
}
